mapper.select:
SELECT up.id, up.user_id, up.post_id, sp.post_code, sp.post_name, up.is_primary, up.status, up.create_time, up.update_time, up.create_user, up.update_user, up.version, up.remark FROM user_post up INNER JOIN sys_post sp ON sp.id = up.post_id WHERE up.user_id = #{userId}
AND sp.post_name LIKE CONCAT('%', #{query.postName}, '%' )
AND sp.post_code LIKE CONCAT('%', #{query.postCode}, '%' )
AND up.status = #{query.status}
ORDER BY up.is_primary DESC, up.create_time DESC, up.id DESC
